INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 9, 'theory', 'Quiz: modules and errors');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 9, 0, 'What does a "live binding" mean for an import in ES modules?', '["The module copies the value on import", "The importer sees changes to the exported variable but cannot change it itself", "The import can be overwritten", "The module runs again on every import"]', 1, 'The binding is read afresh every time: if the module changes the exported variable, all importers see the new value; assigning to the imported name is not allowed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 9, 1, 'How does require in CommonJS fundamentally differ from import in ES modules?', '["require is synchronous and can be called anywhere in the code", "require works only in the browser", "require loads code asynchronously", "There is no difference"]', 0, 'require reads and runs the file synchronously and returns exports; import is static and hoisted to the top, and import() exists for conditional loading.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 9, 2, 'What is the finally block for?', '["It runs only when there is no error", "It replaces catch", "It always runs, including on return and on an exception, so resources are released there", "It repeats the operation"]', 2, 'finally runs on any exit from try: normal, through return, or through an exception.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 9, 3, 'What is the cause field of Error for?', '["It stores the call stack", "It sets the process exit code", "It limits the number of retries", "It lets you wrap the original error in a more meaningful one without losing the root cause"]', 3, 'new Error(''failed to save'', { cause: err }) keeps the chain: the log shows what caused the top-level error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 9, 4, 'Which operations can be safely retried after a failure?', '["Any", "Only idempotent ones, whose repetition does no harm, such as reading", "Only database writes", "None"]', 1, 'Retrying a charge would double the payment, while retrying a read is safe; limit the number of attempts and increase the pause exponentially with jitter.');
